const store = $getWorkflowStaticData('global');
store.sessions ||= {};

const msg = $json.message || {};
const chatId = String(msg.chat?.id || '');
const text = String(msg.text || msg.caption || '').trim();
const session = store.sessions[chatId] || {};

function largestPhotoFileId(message) {
  const photos = message.photo || [];
  if (!photos.length) return '';
  return photos[photos.length - 1].file_id;
}

function screenVideoFileId(message) {
  if (message.video?.file_id) return message.video.file_id;
  if (message.document?.file_id && String(message.document.mime_type || '').startsWith('video/')) return message.document.file_id;
  return '';
}

function audioFileId(message) {
  if (message.voice?.file_id) return message.voice.file_id;
  if (message.audio?.file_id) return message.audio.file_id;
  if (message.document?.file_id && String(message.document.mime_type || '').startsWith('audio/')) return message.document.file_id;
  return '';
}

function newSession() {
  const sid = chatId + '_' + Date.now();
  store.sessions[chatId] = {
    session_id: sid,
    stage: 'need_screen',
    created_at: new Date().toISOString()
  };
  return store.sessions[chatId];
}

function renderSummary(current) {
  return [
    '✅ Материалы приняты, но платный HeyGen еще НЕ запущен.',
    '',
    'Проверка:',
    '1) Запись экрана: есть',
    '2) Фото аватара: есть',
    '3) Голос/аудио: есть',
    '4) Пожелания: ' + (current.wishes || 'без пожеланий'),
    '',
    'Если все верно, отправь ровно слово:',
    'РЕНДЕР',
    '',
    'Если нужно заменить файлы, отправь /new и начни заново. До слова РЕНДЕР кредиты HeyGen не тратятся.'
  ].join('\n');
}

let current = session.session_id ? session : newSession();
let route = 'ask';
let reply = '';

if (/^\/(start|new)/i.test(text)) {
  current = newSession();
  reply = [
    '🎬 Запускаем новый Reels в формате “экран сверху + говорящий человек снизу”.',
    '',
    'Шаг 1: пришли запись экрана Telegram/бота.',
    'Лучше: вертикальное видео 9:16, 15-40 секунд, без лишних пауз, чтобы было видно отправку голосового и результат бота.'
  ].join('\n');
} else if (current.stage === 'need_screen') {
  const fileId = screenVideoFileId(msg);
  if (!fileId) {
    reply = [
      'Пришли именно видео-запись экрана Telegram/бота.',
      '',
      'Формат: обычное видео или video-файл. Фото/текст на этом шаге не подойдут.'
    ].join('\n');
  } else {
    current.screen_file_id = fileId;
    const screenDuration = msg.video?.duration || 0;
    const screenSize = msg.video?.file_size || msg.document?.file_size || 0;
    if (screenDuration && screenDuration > 75) {
      reply = 'Запись экрана слишком длинная. Пришли видео до 60 секунд, чтобы монтаж не получился тяжелым.';
    } else if (screenSize && screenSize > 20 * 1024 * 1024) {
      reply = 'Запись экрана слишком большая для Telegram Bot API. Сожми видео или пришли фрагмент до 20 МБ.';
    } else {
    current.screen_duration = screenDuration;
    current.screen_width = msg.video?.width || 0;
    current.screen_height = msg.video?.height || 0;
    current.screen_size = screenSize;
    current.stage = 'need_avatar';
    reply = [
      '✅ Запись экрана принята.',
      '',
      'Шаг 2: пришли фото или селфи для говорящего HeyGen-человека.',
      'Лучше: лицо крупно, хорошее освещение, один человек, рот и лицо хорошо видны.'
    ].join('\n');
    }
  }
} else if (current.stage === 'need_avatar') {
  const fileId = largestPhotoFileId(msg);
  if (!fileId) {
    reply = 'Теперь пришли фото/селфи для говорящего человека. После этого я попрошу голос.';
  } else {
    current.avatar_file_id = fileId;
    current.stage = 'need_voice';
    reply = [
      '✅ Фото принято.',
      '',
      'Шаг 3: пришли голосовое или аудиофайл с речью для ролика.',
      'Лучше 20-35 секунд, четко, без длинных пауз. Это будет речь для губ и движения HeyGen.'
    ].join('\n');
  }
} else if (current.stage === 'need_voice') {
  const fileId = audioFileId(msg);
  if (!fileId) {
    reply = 'Теперь нужен голос или аудиофайл с речью для ролика.';
  } else {
    const voiceDuration = msg.voice?.duration || msg.audio?.duration || 0;
    const voiceSize = msg.voice?.file_size || msg.audio?.file_size || msg.document?.file_size || 0;
    if (voiceDuration && voiceDuration > 75) {
      reply = 'Голос слишком длинный. Пришли речь до 60 секунд, чтобы не тратить лишние HeyGen-кредиты.';
    } else if (voiceSize && voiceSize > 20 * 1024 * 1024) {
      reply = 'Аудиофайл слишком большой. Пришли голос/аудио до 20 МБ.';
    } else {
    current.voice_file_id = fileId;
    current.voice_duration = voiceDuration;
    current.voice_size = voiceSize;
    current.stage = 'need_wishes';
    reply = [
      '✅ Аудио принято.',
      '',
      'Шаг 4: напиши пожелания к ролику: какой бот/сервис рекламируем, стиль, акценты, CTA.',
      'Если пожеланий нет, отправь: без пожеланий.'
    ].join('\n');
    }
  }
} else if (current.stage === 'need_wishes') {
  if (!text) {
    reply = 'Напиши текстом пожелания к ролику. Если пожеланий нет, отправь: без пожеланий.';
  } else {
    current.wishes = text;
    current.stage = 'need_render_confirm';
    reply = renderSummary(current);
  }
} else if (current.stage === 'need_render_confirm') {
  if (/^(рендер|render)$/i.test(text)) {
    current.stage = 'processing';
    route = 'process';
    reply = 'Запускаю платную сборку Reels.';
  } else {
    reply = renderSummary(current);
  }
} else if (current.stage === 'processing') {
  reply = 'Ролик уже собирается. Новый платный рендер не запускаю. Если хочешь начать заново, отправь /new.';
} else {
  current = newSession();
  reply = 'Начал новый проект. Пришли запись экрана Telegram/бота.';
}

store.sessions[chatId] = current;

return [{
  json: {
    route,
    reply,
    chat_id: chatId,
    session_id: current.session_id,
    screen_file_id: current.screen_file_id || '',
    screen_duration: current.screen_duration || 0,
    screen_width: current.screen_width || 0,
    screen_height: current.screen_height || 0,
    screen_size: current.screen_size || 0,
    avatar_file_id: current.avatar_file_id || '',
    voice_file_id: current.voice_file_id || '',
    wishes: current.wishes || '',
    voice_duration: current.voice_duration || 0,
    voice_size: current.voice_size || 0
  }
}];

const message = $json.output?.find?.((item) => item.type === 'message') || $json.output?.[0];
const raw = String(
  message?.content?.find?.((part) => part.type === 'output_text')?.text ||
  message?.content?.[0]?.text ||
  $json.text ||
  ''
).trim();

function parseJson(value) {
  const cleaned = value.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (_) {}
    }
    return {};
  }
}

const data = parseJson(raw);
const transcript = String($node['OpenAI - Whisper Transcript'].json.text || '').trim();
const wishes = String($node['Code - Telegram Session Router'].json.wishes || '').trim();
const fallbackTitle = transcript ? transcript.split(/[.!?\n]/)[0].slice(0, 60) : 'Reels Factory';
const title = String(data.title || fallbackTitle || 'Reels Factory').replace(/["<>]/g, '').slice(0, 60);
const motion = String(
  data.motion_prompt ||
  ('Natural talking-head vertical Reels video. Confident friendly delivery, subtle head movement, expressive but not exaggerated. User style notes: ' + wishes)
).slice(0, 700);

return [{
  json: {
    raw_model_output: raw,
    title,
    motion_prompt: motion
  }
}];

