if (!binary) {
  throw new Error('Renderer did not return converted original voice mp3 in binary.data');
}
binary.fileName = 'original-voice.mp3';
binary.fileExtension = 'mp3';
binary.mimeType = 'audio/mpeg';
return [item];

const videoId = String($node['Code - Extract HeyGen Video ID'].json.video_id || '').trim();
const store = $getWorkflowStaticData('global');
store.heygenPolls ||= {};
const poll = store.heygenPolls[videoId] || { attempts: 0, max_attempts: 12, started_at: new Date().toISOString() };
poll.attempts = Number(poll.attempts || 0) + 1;
poll.max_attempts = Number(poll.max_attempts || 12);
store.heygenPolls[videoId] = poll;

const data = $json.data || {};
const status = String(data.status || '').toLowerCase();
const urls = [
  data.video_url,
  data.download_url,
  data.url,
  data.video?.url,
  data.video?.download_url,
  data.captioned_video_url
].map((value) => String(value || '').trim()).filter(Boolean);
const videoUrl = urls.find((url) => /^https?:\/\//i.test(url)) || '';
const subtitleUrls = [
  data.subtitle_url,
  data.srt_url,
  data.caption_url,
  data.captions_url,
  data.subtitles?.url,
  data.video?.subtitle_url
].map((value) => String(value || '').trim()).filter(Boolean);
const subtitleUrl = subtitleUrls.find((url) => /^https?:\/\//i.test(url)) || '';
const failure = String(data.failure_message || data.error?.message || $json.error?.message || '').trim();
const failed = status === 'failed' || Boolean(data.failure_code) || /failed|error/i.test(failure);
const completed = Boolean(videoUrl) && (!status || status === 'completed' || status === 'success' || status === 'done');
const timedOut = !completed && !failed && poll.attempts >= poll.max_attempts;
const should_retry = !completed && !failed && !timedOut;

return [{
  json: {
    video_id: videoId,
    status: status || (completed ? 'completed' : failed ? 'failed' : timedOut ? 'timeout' : 'pending'),
    completed,
    pending: should_retry,
    failed,
    timed_out: timedOut,
    should_retry,
    poll_attempt: poll.attempts,
    max_poll_attempts: poll.max_attempts,
    video_url: videoUrl,
    subtitle_url: subtitleUrl,
    failure_code: String(data.failure_code || ''),
    failure_message: failure,
    raw_heygen: $json
  }
}];

const text = String($json.text || '').trim();
if (text.length < 3) {
  throw new Error('Whisper returned empty or too short transcript');
}
return [{ json: { text } }];

const screen = $('HTTP - Renderer Upload Screen Recording').first().json || {};
const avatar = $('HTTP - HeyGen Upload Avatar Asset').first().json || {};
