function extractAssetId(response, label) {
  const id = String(response.data?.asset_id || response.asset_id || response.data?.id || response.id || '').trim();
  if (!id) {
    const message = String(response.error?.message || response.error || response.message || '').slice(0, 700);
    throw new Error(label + ' upload did not return asset_id' + (message ? ': ' + message : ''));
  }
  return id;
}

const screenId = String(screen.screen_id || screen.data?.screen_id || '').trim();
if (!screenId) {
  throw new Error('Renderer did not return screen_id for screen recording');
}

const title = String($node['Code - Normalize Reels Prompt'].json.title || 'Reels Factory').slice(0, 60);

return [{
